import{_ as o,c as r,o as a,a2 as d}from"./chunks/framework.CHomSxuB.js";const g=JSON.parse('{"title":"2 · 历史战线与下注层废弃","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/2-历史战线与下注层废弃.md","filePath":"足球信号雷达/2-历史战线与下注层废弃.md"}'),e={name:"足球信号雷达/2-历史战线与下注层废弃.md"};function n(s,t,h,l,u,i){return a(),r("div",null,t[0]||(t[0]=[d('<h1 id="_2-·-历史战线与下注层废弃" tabindex="-1">2 · 历史战线与下注层废弃 <a class="header-anchor" href="#_2-·-历史战线与下注层废弃" aria-label="Permalink to &quot;2 · 历史战线与下注层废弃&quot;">​</a></h1><blockquote><p>一句话：<strong>这一层记录&quot;为什么足球侧最终只剩信号研究&quot;</strong>——旧裁判层回放为负期望，下注/资金层 2026-09-01 被整体移除。 历史结论（证据）：老裁判层与全链路投注回放均无正期望；&quot;挖参数&quot;路径被 walk-forward 实证为死路。</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p><hr><h2 id="一、旧裁判层-全链路回放判决-负期望" tabindex="-1">一、旧裁判层：全链路回放判决（负期望） <a class="header-anchor" href="#一、旧裁判层-全链路回放判决-负期望" aria-label="Permalink to &quot;一、旧裁判层：全链路回放判决（负期望）&quot;">​</a></h2><p>V5 之前的老架构（&quot;裁判层&quot;：欧赔/亚盘/大小球多路信号汇总成单一 final 裁定 + 自动分注）跑了相当长时间， 在真实全链路回放下交出的总账（口径：逐场实结算、含成本）：</p><ul><li><strong>累计 761 场投注回放：命中 309 注（44.4%），累计 ROI ≈ −1.5%</strong>；</li><li>生产口径（只按实际执行的规则统计）累计收益率 <strong>−5.31%</strong>（2026-09-01 核实）。</li></ul><p><strong>结论：多路信号 + 自动裁定 + 分注执行这条老路，整体是负期望</strong>——不是某一个信号坏，是&quot;汇总裁定&quot;这一层架构本身 没能把方向优势转化成钱。这是 V5 重建的直接动因：砍掉执行层，回到最上游，先把&quot;方向信号&quot;本身做踏实。</p><h2 id="二、08-16-的两记耳光-教训沉淀" tabindex="-1">二、08-16 的两记耳光（教训沉淀） <a class="header-anchor" href="#二、08-16-的两记耳光-教训沉淀" aria-label="Permalink to &quot;二、08-16 的两记耳光（教训沉淀）&quot;">​</a></h2><p><strong>① 爆仓式下单</strong>：曾出现单日 149 注、投入达本金的 149%。事后治理引入&quot;绝对质量门槛 + 动态注额 + 日顶&quot;。 教训：<strong>注数上限不可取</strong>（先到先得会挤掉晚场优质注）；EV 高 ≠ 赢钱——高赔注是坑，提高质量门槛后收益率反而下降，说明&quot;看起来贵的注&quot;大多是被市场定价充分的。</p><p><strong>② 过拟合现形记（本系列最重要的一条方法学证据）</strong>： 在训练段历史里&quot;挖&quot;出来的坏信号剔除方案，<strong>一到样本外验证段就反转</strong>——训练段被优化的表现是噪声拟合，不是规律。 由此确立红线：<strong>同一段历史挖参数（剔除信号/赔率区间/EV 阈值）= 过拟合，方案作废；只有结构规则可信</strong>。 这条纪律后来原样移植进了 <a href="/A股量化验证/0-统计纪律与协议冻结.html">A股量化验证</a> 的预注册协议。</p><h2 id="三、2026-09-01-下注层整体移除-用户决策" tabindex="-1">三、2026-09-01：下注层整体移除（用户决策） <a class="header-anchor" href="#三、2026-09-01-下注层整体移除-用户决策" aria-label="Permalink to &quot;三、2026-09-01：下注层整体移除（用户决策）&quot;">​</a></h2><p>用户拍板：&quot;<strong>不考虑下注，完全移除下注相关逻辑和代码，先把信号做踏实</strong>。&quot;</p><p>移除范围（代码层）：自动下注/结算/权益协程、下注策略与仓位管理全部方案、40+ 下注/回测脚本、站点下注展示。 保留范围：<strong>赔率取数工具</strong>（信号评测与采集共用，口径不变：主流盘临场 T-15 分钟的真实赔率轨迹）、<strong>赛果回填</strong>（信号回验依赖）、<strong>信号 OOS 每日对账</strong>。</p><blockquote><p>至此项目形态收敛为：<strong>采集 → 信号（V5 引擎）→ OOS 评测 → 展示</strong>，与下注相关的历史约定（分流、低赔过滤、仓位、熔断等）全部作废归档。</p></blockquote><h2 id="四、口径纪律-踩过的坑-跨项目通用" tabindex="-1">四、口径纪律（踩过的坑，跨项目通用） <a class="header-anchor" href="#四、口径纪律-踩过的坑-跨项目通用" aria-label="Permalink to &quot;四、口径纪律（踩过的坑，跨项目通用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>教训</th></tr></thead><tbody><tr><td>实时 vs 临场赔率混用</td><td>曾把&quot;赛后赔率&quot;当&quot;实时赔率&quot;用（隐性未来函数）。取数口径钉死：<strong>信号评测只用赛前 T-15 分钟的真实赔率轨迹，禁用 latest/赛后行情</strong>——与 A 股&quot;媒体时间戳不可信、可用时间由规则表映射&quot;是同一类防线</td></tr><tr><td>生产口径 vs 引擎宽口径</td><td>同一系统两套统计曾混用（引擎实时 ROI −13.3% vs 生产严口径 +23.94% 曾被并列引用）。<strong>口径一旦混用，结论全废</strong>；一切引用必须声明口径</td></tr><tr><td>回测结论 ≠ 可执行</td><td>V5 考决的高超额在 OOS 大样本下普遍回落到个位数 pp（见 <a href="./1-V5信号体系与考决.html">1-V5信号体系与考决</a>）——回测说的不算，时间说的才算</td></tr></tbody></table><hr><h2 id="阶段决策时间线" tabindex="-1">阶段决策时间线 <a class="header-anchor" href="#阶段决策时间线" aria-label="Permalink to &quot;阶段决策时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>决策</th><th>性质</th></tr></thead><tbody><tr><td>08-15 前后</td><td>裁判层全链路回放定稿</td><td>证据：负期望（ROI ≈ −1.5%）</td></tr><tr><td>08-16</td><td>爆仓治理 + 过拟合纪律确立</td><td>教训：挖参数方案作废</td></tr><tr><td>08-21</td><td>V5 冻结考决（4 活 1 死）</td><td>证据：结构规则存活</td></tr><tr><td>09-01</td><td><strong>下注层整体移除，只留信号体系</strong></td><td>用户决策：先把信号做踏实</td></tr><tr><td>09-02</td><td>信号 OOS 逐日对账运行中</td><td>观测中（见第 1 篇）</td></tr></tbody></table><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p>',21)]))}const _=o(e,[["render",n]]);export{g as __pageData,_ as default};
